from pathlib import Path
import re, subprocess, tempfile
s=Path('drivers/power/reset/apple-d2365-poweroff.c').read_text()
h=s[s.index('static int apple_d2365_test_status_read'):s.index('\nstatic void apple_d2365_test_status_compare')]
pre='''#include <assert.h>\n#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\ntypedef uint8_t u8;\n#define I2C_M_RD 1\n#define I2C_LOCK_SEGMENT 0\n#define ARRAY_SIZE(x) (sizeof(x)/sizeof((x)[0]))\n#define EIO 5\nstruct i2c_adapter { int unused; };\nstruct i2c_client { struct i2c_adapter *adapter; int addr; };\nstruct i2c_msg { int addr, flags, len; u8 *buf; };\nstatic int locked, ncall, counts[4], results[4];\nstatic void i2c_lock_bus(struct i2c_adapter *a, int l) { assert(!locked); locked=1; }\nstatic void i2c_unlock_bus(struct i2c_adapter *a, int l) { assert(locked); locked=0; }\nstatic int __i2c_transfer(struct i2c_adapter *a, struct i2c_msg *m, int n) { assert(locked); counts[ncall]=n; if(ncall==0) { assert(m[0].addr==0x3c && m[0].flags==0 && m[0].len==2 && m[0].buf[0]==1 && m[0].buf[1]==0x8a); if(n==2) assert(m[1].flags==I2C_M_RD && m[1].len==1); } else assert(m[0].flags==I2C_M_RD && m[0].len==1); return results[ncall++]; }\n'''
post='''int main(void) { struct i2c_adapter a; struct i2c_client c={&a,0x3c}; u8 v; results[0]=2; assert(!apple_d2365_test_status_read(&c, false, &v)); assert(ncall==1 && counts[0]==2 && !locked); ncall=0; results[0]=1; results[1]=1; assert(!apple_d2365_test_status_read(&c, true, &v)); assert(ncall==2 && counts[0]==1 && counts[1]==1 && !locked); ncall=0; results[0]=0; assert(apple_d2365_test_status_read(&c, true, &v)==-EIO); assert(ncall==1 && !locked); ncall=0; results[0]=1; results[1]=-9; assert(apple_d2365_test_status_read(&c, true, &v)==-9); assert(ncall==2 && !locked); ncall=0; results[0]=1; assert(apple_d2365_test_status_read(&c, false, &v)==-EIO); assert(!locked); return 0; }'''
with tempfile.TemporaryDirectory() as d:
 p=Path(d)/'t.c';p.write_text(pre+h+post);subprocess.run(['cc','-std=c11','-Wall','-Wextra','-Wno-unused-parameter',str(p),'-o',str(Path(d)/'t')],check=True);subprocess.run([str(Path(d)/'t')],check=True)
